alter table public.demo_personas add column studio_avatar_url text;
alter table public.demo_personas add column face_source_reference text;
-- Portrait sources are not prepared models. Inference still requires face_asset_reference and readiness flags.
grant select(studio_avatar_url) on public.demo_personas to authenticated;
create table public.demo_persona_assets (
 id uuid primary key default gen_random_uuid(), demo_persona_id uuid not null references public.demo_personas(id) on delete cascade,
 asset_type text not null check(asset_type in ('avatar','image_source','face_model','voice_model')),
 storage_path text not null, mime_type text not null,
 role text not null check(role in ('thumbnail','preview','studio','face_source','face_model','voice_model')),
 metadata jsonb not null default '{}', created_at timestamptz not null default now(),
 unique(demo_persona_id,role)
);
create index demo_assets_identity on public.demo_persona_assets(demo_persona_id,role);
alter table public.demo_persona_assets enable row level security;
revoke all on public.demo_persona_assets from anon,authenticated;
-- Asset mappings/models are server-owned. Public avatar URLs remain on demo_personas.

-- Generated avatar seed updates; preserve administrator-configured identities.
update public.demo_personas set description='Warm, confident and professional. A synthetic creator identity with natural curls and a polished charcoal look.',thumbnail_url='/demos/amara/thumbnail.webp',preview_image_url='/demos/amara/preview.webp',studio_avatar_url='/demos/amara/studio.webp',face_source_reference='/demos/amara/face-source.jpg',featured=true,metadata=metadata || '{"placeholder":false,"ownership":"Shapre original synthetic adult avatar","voice_profile":"Warm feminine","asset_license":"Original AI-generated Shapre product artwork","avatar_ready":true,"asset_bundle_version":1,"generation":"built-in image_gen","face_source_ready":true}'::jsonb where slug='amara' and (metadata->>'placeholder'='true' or metadata->>'asset_bundle_version'='1');
